css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent !important;
}

.tabla-widget {
  display: grid;
  grid-template-rows: 70px minmax(0, 1fr);
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  opacity: var(--w-opacity, 1);
}

.tabla-widget svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: Bahnschrift, "Segoe UI", Arial, sans-serif;
  user-select: none;
}

.col-heading {
  fill: #194e68;
  font-weight: 700;
  text-anchor: middle;
}

.row-heading {
  fill: #243b49;
  font-weight: 700;
  font-style: italic;
}

.row-label-cell {
  fill: #e5ebef;
  stroke: #738796;
  stroke-width: 0.9;
}

.data-cell {
  fill: #f7fafc;
  stroke: #8798a4;
  stroke-width: 0.8;
}

.data-cell.alternate {
  fill: #eef3f6;
}

/* Solo se dibuja la barra; no existe carril de fondo. */
.meter-fill.red {
  fill: url(#red-bar-gradient);
  stroke: #930606;
  stroke-width: 0.6;
}

.meter-fill.blue {
  fill: url(#blue-bar-gradient);
  stroke: #075273;
  stroke-width: 0.6;
}

.grid-line {
  stroke: #879aa5;
  stroke-width: 0.8;
  stroke-dasharray: 3 3;
}

.grid-zero {
  stroke: #253e4e;
  stroke-width: 1.8;
}

.axis-number {
  fill: #263d4b;
  font-family: "IBM Plex Mono", Consolas, "Liberation Mono", monospace;
  font-weight: 600;
  text-anchor: end;
  font-variant-numeric: tabular-nums;
}
/* Solo texto: encabezado transparente con la tipografía del ejemplo de recetas. */
.lazos-header {
  min-width: 0;
  padding: 14px 30px 0;
  overflow: hidden;
  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
  user-select: none;
}

.lazos-title {
  margin: 0;
  padding: 0;
  color: #0E5B67;
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  white-space: nowrap;
}

.lazos-subtitle {
  margin: 5px 0 0;
  padding: 0;
  color: #728DA5;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
}

.tabla-chart {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

