"use strict";

(function () {
  const SVG_NS = "http://www.w3.org/2000/svg";

  const DEFAULT_WIDTH = 1610;
  const DEFAULT_HEIGHT = 755;
  const HEADER_HEIGHT = 70;
  const DEFAULT_TITLE = "Error de lazos / Línea 4";
  const DEFAULT_SUBTITLE = "Desviación de los lazos de control del proceso";

  let headerTitle = null;
  let headerSubtitle = null;

  /* NOMBRE: Título//Subtítulo. Con Título// se oculta el subtítulo.
   * Sin NOMBRE se muestran ambos textos predeterminados.
   * Sin separador se personaliza solo el título.
   */
  function updateHeader(widget) {
    if (!headerTitle || !headerSubtitle) return;
    const name = widget && typeof widget.name === "string"
      ? widget.name.trim() : "";
    const separator = name.indexOf("//");
    const titleText = separator >= 0 ? name.slice(0, separator).trim() : name;
    const subtitleText = separator >= 0
      ? name.slice(separator + 2).trim() : DEFAULT_SUBTITLE;

    headerTitle.textContent = titleText || DEFAULT_TITLE;
    headerSubtitle.textContent = subtitleText;
    headerSubtitle.hidden = subtitleText === "";
    fitHeader();
  }

  function fitHeader() {
    [[headerTitle, 28], [headerSubtitle, 14]].forEach(function (entry) {
      const element = entry[0];
      if (!element || element.hidden) return;
      const size = entry[1];
      element.style.fontSize = size + "px";
      const available = element.clientWidth;
      if (available > 0 && element.scrollWidth > available) {
        element.style.fontSize = (size * available / element.scrollWidth) + "px";
      }
    });
  }

  const SIDE_MARGIN = 30;
  const VERTICAL_MARGIN = 10;
  const RESERVED_RIGHT_WIDTH = 340;

  /*
   * Orden de vinculación:
   *
   * principal (BOOL) -> var1  (número): CUBA 8
   * var2      (BOOL) -> var3  (número): CUBA 9
   * ...
   * var34     (BOOL) -> var35 (número): SECA ZONA 5
   */
  const POSITIONS = [
    { label: "CUBA 8" },
    { label: "CUBA 9" },
    { label: "CUBA 10" },
    { label: "CUBA 11" },

    {
      label: "CALEF. RIZADO",
      lines: ["CALEF.", "RIZADO"]
    },
    {
      label: "FLUJO AGUA",
      lines: ["FLUJO", "AGUA"]
    },
    {
      label: "TANQUE MEZCLA",
      lines: ["TANQUE", "MEZCLA"]
    },
    {
      label: "TANQUE DOSIFIC.",
      lines: ["TANQUE", "DOSIFIC."]
    },
    {
      label: "VAPOR CAJAS",
      lines: ["VAPOR", "CAJAS"]
    },
    {
      label: "FLEIB. ZONA 1",
      lines: ["FLEIB.", "ZONA 1"]
    },
    {
      label: "FLEIB. ZONA 2",
      lines: ["FLEIB.", "ZONA 2"]
    },
    {
      label: "FLEIB. ZONA 3",
      lines: ["FLEIB.", "ZONA 3"]
    },
    {
      label: "FLUJO ZONA 1",
      lines: ["FLUJO", "ZONA 1"]
    },

    {
      label: "SECA ZONA 1",
      lines: ["SECA", "ZONA 1"]
    },
    {
      label: "SECA ZONA 2",
      lines: ["SECA", "ZONA 2"]
    },
    {
      label: "SECA ZONA 3",
      lines: ["SECA", "ZONA 3"]
    },
    {
      label: "SECA ZONA 4",
      lines: ["SECA", "ZONA 4"]
    },
    {
      label: "SECA ZONA 5",
      lines: ["SECA", "ZONA 5"]
    }
  ].map(function (position, index) {
    return {
      label: position.label,
      lines: position.lines || [position.label],
      boolAlias:
        index === 0
          ? "principal"
          : "var" + (index * 2),
      numericAlias:
        "var" + (index * 2 + 1)
    };
  });

  const SUPERIOR = POSITIONS.slice(0, 4);
  const INFERIOR_IZQUIERDA = POSITIONS.slice(4, 13);
  const INFERIOR_DERECHA = POSITIONS.slice(13, 18);

  const ROW_LABELS = [
    "T real",
    "T nominal",
    "T diferencia",
    "% válvula"
  ];

  let host = null;
  let svg = null;
  let resizeObserver = null;
  let pendingFrame = null;

  let lastWidth = 0;
  let lastHeight = 0;

  let latestWidget = null;
  let hasReceivedUpdate = false;
  let meters = [];

  function clamp(value, minimum, maximum) {
    return Math.max(
      minimum,
      Math.min(maximum, value)
    );
  }

  function make(tag, attributes, parent, content) {
    const element = document.createElementNS(
      SVG_NS,
      tag
    );

    Object.keys(attributes || {}).forEach(
      function (key) {
        element.setAttribute(key, attributes[key]);
      }
    );

    if (content !== undefined) {
      element.textContent = content;
    }

    (parent || svg).appendChild(element);
    return element;
  }

  function addGradient(defs, id, colors) {
    const gradient = make(
      "linearGradient",
      {
        id: id,
        x1: "0%",
        y1: "0%",
        x2: "100%",
        y2: "0%"
      },
      defs
    );

    make(
      "stop",
      {
        offset: "0%",
        "stop-color": colors[0]
      },
      gradient
    );

    make(
      "stop",
      {
        offset: "48%",
        "stop-color": colors[1]
      },
      gradient
    );

    make(
      "stop",
      {
        offset: "100%",
        "stop-color": colors[2]
      },
      gradient
    );
  }

  function addDefinitions() {
    const defs = make("defs");

    addGradient(
      defs,
      "red-bar-gradient",
      ["#991c27", "#d03b46", "#a8202c"]
    );

    addGradient(
      defs,
      "blue-bar-gradient",
      ["#075273", "#2588b2", "#0a638f"]
    );
  }

  function drawTable(items, positions, options) {
    const columnWidth = options.columnWidth;
    const rowHeight = options.rowHeight;
    const tableY = options.tableY;

    items.forEach(function (item, column) {
      const x = positions[column];

      item.lines.forEach(function (line, lineIndex) {
        make(
          "text",
          {
            x: x + columnWidth / 2,
            y:
              options.headingY +
              lineIndex * options.lineGap,
            class: "col-heading",
            "font-size": options.headingFont
          },
          svg,
          line
        );
      });

      for (let row = 0; row < 4; row += 1) {
        make(
          "rect",
          {
            x: x,
            y: tableY + row * rowHeight,
            width: columnWidth,
            height: rowHeight,
            class:
              row % 2 === 0
                ? "data-cell"
                : "data-cell alternate"
          }
        );

        /* Las cuatro celdas quedan vacías. */
      }
    });

    if (!options.showRowLabels) return;

    ROW_LABELS.forEach(function (label, row) {
      const y = tableY + row * rowHeight;

      make(
        "rect",
        {
          x: options.labelX,
          y: y,
          width: options.labelWidth,
          height: rowHeight,
          class: "row-label-cell"
        }
      );

      make(
        "text",
        {
          x: options.labelX + 8,
          y: y + rowHeight * 0.72,
          class: "row-heading",
          "font-size": options.rowFont
        },
        svg,
        label
      );
    });
  }

  function drawGraph(items, positions, options) {
    const top = options.top;
    const bottom = options.bottom;
    const middle = (top + bottom) / 2;

    /* Mismo grosor que la última versión. */
    const barWidth = clamp(
      options.columnWidth * 0.55,
      2,
      40
    );

    items.forEach(function (item, index) {
      const x =
        positions[index] +
        (options.columnWidth - barWidth) / 2;

      const group = make("g");

      const title = make(
        "title",
        {},
        group,
        item.label + ": 0"
      );

      const bar = make(
        "rect",
        {
          x: x,
          y: middle,
          width: barWidth,
          height: 0,
          rx: 1,
          class: "meter-fill red",
          display: "none"
        },
        group
      );

      meters.push({
        item: item,
        bar: bar,
        title: title,
        middle: middle,
        halfHeight: (bottom - top) / 2,
        range: options.range
      });
    });

    for (let step = 0; step <= 10; step += 1) {
      const y =
        top +
        step * (bottom - top) / 10;

      const value =
        options.range -
        step * 2 * options.range / 10;

      make(
        "line",
        {
          x1: options.left,
          y1: y,
          x2: options.right,
          y2: y,
          class:
            step === 5
              ? "grid-zero"
              : "grid-line"
        }
      );

      make(
        "text",
        {
          x: options.axisX,
          y: y + options.axisFont * 0.32,
          class: "axis-number",
          "font-size": options.axisFont
        },
        svg,
        String(value)
      );
    }
  }

  function readValue(widget, alias) {
    if (!widget) return undefined;

    if (alias === "principal") {
      return widget.value;
    }

    const variables = widget.vars;

    if (
      !variables ||
      typeof variables !== "object" ||
      !Object.prototype.hasOwnProperty.call(
        variables,
        alias
      )
    ) {
      return undefined;
    }

    const entry = variables[alias];

    /* Compatible con el widget de lectura adjunto. */
    if (
      entry !== null &&
      typeof entry === "object" &&
      Object.prototype.hasOwnProperty.call(
        entry,
        "value"
      )
    ) {
      return entry.value;
    }

    return entry;
  }

  function toNumber(raw) {
    if (typeof raw === "number") {
      return Number.isFinite(raw) ? raw : null;
    }

    if (
      typeof raw === "string" &&
      raw.trim() !== ""
    ) {
      const number = Number(
        raw.trim().replace(",", ".")
      );

      return Number.isFinite(number)
        ? number
        : null;
    }

    return null;
  }

  function isBlue(raw) {
    if (raw === true || raw === 1) {
      return true;
    }

    if (typeof raw === "string") {
      const text = raw.trim().toLowerCase();

      return (
        text === "1" ||
        text === "true"
      );
    }

    return false;
  }

  function updateMeters() {
    if (!hasReceivedUpdate) return;

    meters.forEach(function (meter) {
      const numericRaw = readValue(
        latestWidget,
        meter.item.numericAlias
      );

      const boolRaw = readValue(
        latestWidget,
        meter.item.boolAlias
      );

      const parsed = toNumber(numericRaw);
      const value = parsed === null ? 0 : parsed;

      /* Sin lectura o en cero: barra invisible. */
      if (value === 0) {
        meter.bar.setAttribute("display", "none");
        meter.bar.setAttribute("height", "0");
        meter.title.textContent =
          meter.item.label + ": 0";
        return;
      }

      const limited = clamp(
        value,
        -meter.range,
        meter.range
      );

      const barHeight =
        Math.abs(limited) /
        meter.range *
        meter.halfHeight;

      const y =
        limited > 0
          ? meter.middle - barHeight
          : meter.middle;

      meter.bar.setAttribute(
        "class",
        isBlue(boolRaw)
          ? "meter-fill blue"
          : "meter-fill red"
      );

      meter.bar.setAttribute("display", "inline");
      meter.bar.setAttribute("y", y.toFixed(2));
      meter.bar.setAttribute(
        "height",
        barHeight.toFixed(2)
      );

      meter.title.textContent =
        meter.item.label +
        ": " +
        value +
        (
          limited !== value
            ? " (barra limitada a " +
              limited +
              ")"
            : ""
        );
    });
  }

  function draw() {
    if (!host || !svg) return;

    const width =
      host.clientWidth || DEFAULT_WIDTH;

    const height =
      host.clientHeight || (DEFAULT_HEIGHT - HEADER_HEIGHT);

    if (width <= 0 || height <= 0) return;

    fitHeader();

    lastWidth = width;
    lastHeight = height;

    svg.setAttribute(
      "viewBox",
      "0 0 " + width + " " + height
    );

    svg.setAttribute(
      "preserveAspectRatio",
      "none"
    );

    svg.replaceChildren();
    meters = [];

    make(
      "title",
      {},
      svg,
      "Cubas 8 a 11 y zonas de secado"
    );

    addDefinitions();

    const contentHeight =
      height - 2 * VERTICAL_MARGIN;

    const rowHeight = Math.max(
      11,
      contentHeight * 0.028
    );

    const labelWidth = clamp(
      width * 0.077,
      70,
      122
    );

    /*
     * Se reservan 340 px a la derecha.
     * Si el widget se hace muy estrecho,
     * la reserva disminuye para evitar que
     * las columnas desaparezcan.
     */
    const dataLeft =
      SIDE_MARGIN + labelWidth;

    const availableWidth =
      width - SIDE_MARGIN - dataLeft;

    const reservedWidth = Math.min(
      RESERVED_RIGHT_WIDTH,
      Math.max(0, availableWidth - 550)
    );

    const dataRight =
      width -
      SIDE_MARGIN -
      reservedWidth;

    const dataWidth =
      dataRight - dataLeft;

    /*
     * Grupo superior: cuatro cubas centradas
     * sobre el área de los gráficos.
     */
    const topDataWidth = Math.min(
      dataWidth * 0.34,
      460
    );

    const topColumnWidth =
      topDataWidth / SUPERIOR.length;

    const topDataLeft =
      dataLeft +
      dataWidth * 0.54 -
      topDataWidth / 2;

    const topLabelX =
      topDataLeft - labelWidth;

    const topX = SUPERIOR.map(
      function (_, index) {
        return (
          topDataLeft +
          index * topColumnWidth
        );
      }
    );

    /*
     * Parte inferior:
     * nueve columnas ±5, separación,
     * y cinco columnas ±15.
     */
    const bottomGap = clamp(
      dataWidth * 0.08,
      35,
      110
    );

    const bottomColumnWidth =
      (dataWidth - bottomGap) /
      (INFERIOR_IZQUIERDA.length + INFERIOR_DERECHA.length);

    const bottomLeftX =
      INFERIOR_IZQUIERDA.map(
        function (_, index) {
          return (
            dataLeft +
            index * bottomColumnWidth
          );
        }
      );

    const bottomRightStart =
      dataLeft +
      INFERIOR_IZQUIERDA.length * bottomColumnWidth +
      bottomGap;

    const bottomRightX =
      INFERIOR_DERECHA.map(
        function (_, index) {
          return (
            bottomRightStart +
            index * bottomColumnWidth
          );
        }
      );

    const topHeadingFont = clamp(
      topColumnWidth * 0.18,
      7,
      18
    );

    const bottomHeadingFont = clamp(
      bottomColumnWidth * 0.18,
      7,
      18
    );

    const rowFont = clamp(
      rowHeight * 0.78,
      8,
      16
    );

    const axisFont = clamp(
      rowHeight * 0.64,
      8,
      13
    );

    const topTableY =
      VERTICAL_MARGIN +
      contentHeight * 0.045;

    const topChartTop = Math.max(
      topTableY + 4 * rowHeight + 14,
      VERTICAL_MARGIN +
        contentHeight * 0.18
    );

    const topChartBottom =
      VERTICAL_MARGIN +
      contentHeight * 0.49;

    const bottomTableY =
      VERTICAL_MARGIN +
      contentHeight * 0.58;

    const bottomChartTop = Math.max(
      bottomTableY + 4 * rowHeight + 14,
      VERTICAL_MARGIN +
        contentHeight * 0.71
    );

    const bottomChartBottom =
      height -
      VERTICAL_MARGIN -
      axisFont * 0.55 -
      2;

    const headingLineGap = clamp(
      rowHeight * 0.64,
      8,
      13
    );

    drawTable(
      SUPERIOR,
      topX,
      {
        columnWidth: topColumnWidth,
        rowHeight: rowHeight,
        tableY: topTableY,
        headingY: topTableY - 8,
        headingFont: topHeadingFont,
        lineGap: headingLineGap,
        rowFont: rowFont,
        labelX: topLabelX,
        labelWidth: labelWidth,
        showRowLabels: true
      }
    );

    drawGraph(
      SUPERIOR,
      topX,
      {
        columnWidth: topColumnWidth,
        top: topChartTop,
        bottom: topChartBottom,
        range: 5,
        left: topDataLeft,
        right: topDataLeft + topDataWidth,
        axisX: topDataLeft - 8,
        axisFont: axisFont
      }
    );

    const bottomTableOptions = {
      columnWidth: bottomColumnWidth,
      rowHeight: rowHeight,
      tableY: bottomTableY,
      headingY:
        bottomTableY -
        headingLineGap -
        8,
      headingFont: bottomHeadingFont,
      lineGap: headingLineGap,
      rowFont: rowFont,
      labelX: SIDE_MARGIN,
      labelWidth: labelWidth
    };

    drawTable(
      INFERIOR_IZQUIERDA,
      bottomLeftX,
      Object.assign(
        {},
        bottomTableOptions,
        { showRowLabels: true }
      )
    );

    drawTable(
      INFERIOR_DERECHA,
      bottomRightX,
      Object.assign(
        {},
        bottomTableOptions,
        { showRowLabels: false }
      )
    );

    drawGraph(
      INFERIOR_IZQUIERDA,
      bottomLeftX,
      {
        columnWidth: bottomColumnWidth,
        top: bottomChartTop,
        bottom: bottomChartBottom,
        range: 5,
        left: dataLeft,
        right:
          dataLeft +
          INFERIOR_IZQUIERDA.length * bottomColumnWidth,
        axisX: dataLeft - 8,
        axisFont: axisFont
      }
    );

    drawGraph(
      INFERIOR_DERECHA,
      bottomRightX,
      {
        columnWidth: bottomColumnWidth,
        top: bottomChartTop,
        bottom: bottomChartBottom,
        range: 15,
        left: bottomRightStart,
        right: dataRight,
        axisX: bottomRightStart - 8,
        axisFont: axisFont
      }
    );

    updateMeters();
  }

  function scheduleDraw() {
    if (pendingFrame !== null) return;

    pendingFrame = requestAnimationFrame(
      function () {
        pendingFrame = null;

        if (!host) return;

        if (
          host.clientWidth !== lastWidth ||
          host.clientHeight !== lastHeight
        ) {
          draw();
        }
      }
    );
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    hasReceivedUpdate = true;
    updateHeader(widget);
    updateMeters();
  };

  function initialize() {
    host = document.querySelector(
      ".tabla-chart"
    );

    svg = document.getElementById(
      "tabla-svg"
    );

    if (!host || !svg) return;

    headerTitle = document.querySelector(".lazos-title");
    headerSubtitle = document.querySelector(".lazos-subtitle");
    updateHeader(latestWidget || window.WIDGET || null);

    /* Se inicia sin barras visibles. */
    draw();

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(
        scheduleDraw
      );

      resizeObserver.observe(host);
    } else {
      window.addEventListener(
        "resize",
        scheduleDraw
      );
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
